        print(f\"{e['exp_id']} | status={e['status']} | conclusion={e.get('conclusion','-')} | metrics={json.dumps(e.get('metrics',{}))[:200]}\")

print('---PREPARING---')
for e in exps:
    if e.get('status') == 'PREPARING':
        print(f\"{e['exp_id']} | hypothesis={str(e.get('hypothesis','-'))[:100]}\")
